'use strict';
const $ = (s, root = document) => root.querySelector(s);
const esc = s => String(s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons = {today:'M3 4h18v16H3z M3 9h18 M8 2v4 M16 2v4',inbox:'M3 4h18v16H3z M3 13h5l2 3h4l2-3h5',tasks:'M9 5h12 M9 12h12 M9 19h12 M2 5l2 2 3-4 M2 12l2 2 3-4 M2 19l2 2 3-4',calendar:'M3 5h18v16H3z M3 10h18 M8 2v5 M16 2v5 M8 14h2 M14 14h2',questions:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 4 M12 17v1 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',sources:'M8 7H4v14h14v-4 M10 3h11v11H10z',settings:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6'};
const routes = {today:'Сегодня',inbox:'Входящие',tasks:'Задачи',calendar:'Календарь',questions:'Уточнения',sources:'Источники',settings:'Настройки'};
const initialMessages = [
 {id:1,source:'E-mail',icon:'@',person:'Алексей · команда проекта',time:'09:18',title:'Согласовать смету до 16:00',summary:'Нужен ответ по двум позициям в смете. Срок сегодня, важность отправителя — 5.',body:'Доброе утро! Посмотрите, пожалуйста, две спорные позиции в смете по офису. Нужен ваш ответ сегодня до 16:00, чтобы завтра заказать материалы.',area:'Работа',importance:5,urgent:true,deadline:'10 сентября, 16:00',read:false},
 {id:2,source:'WhatsApp',icon:'W',person:'Марина · сервис дома',time:'08:42',title:'Подтвердить время визита мастера',summary:'Мастер может приехать завтра в 18:00. Подтверждение просят сегодня.',body:'Здравствуйте! Мастер свободен завтра, 11 сентября, в 18:00. Подтвердите, пожалуйста, до 18:00 сегодня, удобно ли вам это время.',area:'Дом и быт',importance:4,urgent:true,deadline:'10 сентября, 18:00',read:false},
 {id:3,source:'Telegram',icon:'T',person:'Дмитрий · рабочая группа',time:'Вчера',title:'Список вопросов к встрече',summary:'Срок был вчера в 17:00. Нужно уточнить, отправлен ли список.',body:'Пришлите, пожалуйста, вопросы к нашей встрече до 17:00 9 сентября. Я объединю их в одну повестку.',area:'Работа',importance:4,overdue:true,deadline:'9 сентября, 17:00',read:false},
 {id:4,source:'Telegram',icon:'T',person:'Анна · команда проекта',time:'09:05',title:'«Давай посмотрим договор на неделе»',summary:'Неясно, это поручение вам или предложение совместного обсуждения.',body:'Давай посмотрим договор на неделе. Кажется, условия по срокам немного поменялись.',area:'Работа',importance:3,question:true,read:false},
 {id:5,source:'RSS',icon:'R',person:'Практика обучения',time:'08:30',title:'Как лучше запоминать прочитанное',summary:'Короткие заметки и повторение через интервалы помогают закреплять новые знания.',body:'После чтения попробуйте записать три главные мысли своими словами. Вернитесь к заметке через несколько дней и проверьте, что удалось вспомнить без подсказки.',area:'Развитие и обучение',importance:2,read:false},
 {id:6,source:'YouTube',icon:'Y',person:'Готовим дома',time:'08:10',title:'Три простых ужина за 20 минут',summary:'Название и описание видео: овощи, рыба и паста. Видео не анализировалось.',body:'Название: Три простых ужина за 20 минут.\nОписание: В этом выпуске готовим овощи в духовке, рыбу с гарниром и пасту. Только название и описание; содержание ролика в прототипе не анализируется.',area:'Дом и быт',importance:1,read:true},
 {id:7,source:'ВКонтакте',icon:'VK',person:'Выходные рядом',time:'07:50',title:'Прогулка по побережью в субботу',summary:'Идея для свободного дня. Обязательного действия или срока нет.',body:'В субботу предлагаем прогулку по побережью. Маршрут без сложных подъёмов, можно присоединиться на удобном участке.',area:'Отдых и увлечения',importance:2,read:false},
 {id:8,source:'E-mail',icon:'@',person:'Алексей · команда проекта',time:'09:25',title:'Дополнение к смете',summary:'Уточнение к первому письму. Объединено с задачей согласования сметы.',body:'Дополнение: по второй позиции оставляем прежнюю цену. Пожалуйста, учтите это при согласовании сметы сегодня до 16:00.',area:'Работа',importance:5,urgent:true,deadline:'10 сентября, 16:00',read:false}
];
const initialTasks = [
 {id:1,title:'Согласовать две позиции в смете',area:'Работа',importance:5,deadline:'Сегодня, 16:00',slot:'Сегодня, 13:00–13:30',date:'2026-09-10',time:'13:00',duration:30,status:'proposed',messages:[1,8],explanation:'30 минут до конца рабочего дня. Два письма объединены в одну задачу.'},
 {id:2,title:'Подтвердить визит мастера',area:'Дом и быт',importance:4,deadline:'Сегодня, 18:00',slot:'Сегодня, 15:30–15:45',date:'2026-09-10',time:'15:30',duration:15,status:'proposed',messages:[2],explanation:'Короткое личное дело после рабочего времени.'},
 {id:3,title:'Подготовить вопросы к встрече',area:'Работа',importance:4,deadline:'Вчера, 17:00',slot:'Вчера, 16:00–16:30',date:'2026-09-09',time:'16:00',duration:30,status:'overdue',messages:[3],explanation:'Запланированное время прошло. Нужен ваш ответ о выполнении.'},
 {id:4,title:'Сверить план расходов',area:'Финансы',importance:3,deadline:'Пятница',slot:'Сегодня, 11:00–11:45',date:'2026-09-10',time:'11:00',duration:45,status:'planned',messages:[],explanation:'Утверждено пользователем.'}
];
const areasDefault=['Работа','Дом и быт','Семья и личное','Здоровье','Финансы','Развитие и обучение','Отдых и увлечения'];
let state; let view='today'; let inboxFilter='all'; let taskFilter='all'; let search=''; let sphere='all';
function resetState(){state={messages:structuredClone(initialMessages),tasks:structuredClone(initialTasks),areas:[...areasDefault],questionResolved:false,sourceHidden:false,sourceKept:false,settings:{interval:60,inactivity:1,urgent:24,reserve:20,quietStart:'21:00',quietEnd:'08:00',autostart:true},lastCheck:'10:00'};}
resetState();
const badge=(label,color='')=>`<span class="badge ${color}">${esc(label)}</span>`;
const button=(text,action,id='',primary=false)=>`<button class="btn ${primary?'primary':''}" data-action="${action}" data-id="${id}">${text}</button>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow">Четверг, 10 сентября</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${action}</div>`;}
function renderNav(){ $('#nav').innerHTML=Object.entries(routes).map(([key,label])=>`<a class="nav-link ${view===key?'active':''}" href="#${key}" ${view===key?'aria-current="page"':''}><svg class="nav-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="${icons[key]}"/></svg>${label}${key==='inbox'?`<span class="count">${state.messages.filter(m=>!m.read).length}</span>`:key==='questions'&&!state.questionResolved?'<span class="count">1</span>':''}</a>`).join('');$('#crumb').textContent=routes[view];}
function messageRow(m){return `<article class="message-row"><span class="source-icon ${m.source==='WhatsApp'?'green':['RSS','YouTube'].includes(m.source)?'orange':''}">${m.icon}</span><div class="row-content"><div class="row-meta"><span>${esc(m.person)} · ${m.source}</span><span>${m.time}${m.read?' · прочитано':''}</span></div><button class="row-title" data-action="message" data-id="${m.id}">${esc(m.title)}</button><p class="row-summary">${esc(m.summary)}</p><div class="tags">${badge(m.area)}${m.overdue?badge('Просрочено','red'):m.urgent?badge('Срочное','red'):''}${m.importance>=4?badge(`Важность ${m.importance}/5`,'blue'):''}${m.question&&!state.questionResolved?badge('Требует уточнения','amber'):''}</div></div></article>`;}
const statusNames={proposed:'Предложена',planned:'Запланирована',overdue:'Нужно уточнить',done:'Выполнена',deferred:'Отложена',rejected:'Отклонена',waiting:'Ожидание'};
function taskCard(t){return `<article class="task-card"><div class="task-title"><h3>${esc(t.title)}</h3>${badge(statusNames[t.status],t.status==='done'?'green':t.status==='overdue'?'red':t.status==='proposed'?'blue':'')}</div><div class="tags">${badge(t.area)}${badge(`${t.importance}/5`,'blue')}</div><div class="task-info">Срок: ${esc(t.deadline)} · Оценка: ${t.duration} мин${t.messages.length?` · ${t.messages.length} сообщ.`:''}</div>${['proposed','planned','overdue'].includes(t.status)?`<div class="proposal"><strong>${esc(t.slot)}</strong><br>${esc(t.explanation)}</div>`:''}${t.reason?`<p class="row-summary">Причина: ${esc(t.reason)}</p>`:''}<div class="actions">${t.status==='proposed'?button('Утвердить время','approve',t.id,true)+button('Изменить','edit-task',t.id)+button('Отложить','defer',t.id)+button('Отклонить','reject',t.id):t.status==='overdue'?button('Уже выполнена','done',t.id)+button('Не сделана →','reason',t.id,true):t.status==='planned'?button('Выполнено','done',t.id)+button('Перенести','edit-task',t.id):['deferred','waiting'].includes(t.status)?button('Выбрать время','edit-task',t.id):''}${t.messages.length?button('Источники','task-sources',t.id):''}</div></article>`;}
function today(){let proposed=state.tasks.filter(t=>t.status==='proposed');return heading('Всё важное — перед вами','Начните с того, что требует вашего решения.',button('↻ Проверить сейчас','check'))+`<section class="stats" aria-label="Обзор"><div class="stat"><div class="stat-label">Новых сообщений</div><div class="stat-value">${state.messages.filter(m=>!m.read).length}</div><div class="stat-note">Из 6 источников · примеры</div></div><div class="stat"><div class="stat-label">Срочных сообщений</div><div class="stat-value red">${state.messages.filter(m=>m.urgent).length}</div><div class="stat-note">Срок в ближайшие ${state.settings.urgent} ч</div></div><div class="stat"><div class="stat-label">Задач на утверждение</div><div class="stat-value blue">${proposed.length}</div><div class="stat-note">Ожидают вашего решения</div></div><div class="stat"><div class="stat-label">Требует уточнения</div><div class="stat-value">${state.questionResolved?0:1}</div><div class="stat-note">Короткий вопрос от ИИ</div></div></section><div class="grid"><div><section class="panel attention"><div class="panel-head"><h2 class="attention-title"><span class="attention-dot"></span>Требует внимания</h2>${badge('24 часа','red')}</div>${state.messages.filter(m=>m.urgent||m.overdue).slice(0,3).map(messageRow).join('')}</section><section class="panel"><div class="panel-head"><h2>Предлагаю добавить в план</h2><a class="link-button" href="#tasks">Все задачи →</a></div>${proposed.length?proposed.map(taskCard).join(''):'<div class="empty">Все предложения рассмотрены.<br>Утверждённые задачи появились в календаре.</div>'}</section></div><div><section class="panel"><div class="panel-head"><h2>План на сегодня</h2><a class="link-button" href="#calendar">Открыть →</a></div><div class="timeline"><div class="time-row"><span class="time-label">10:00</span><div class="time-block">Встреча команды<small>Фиксированное событие · 30 мин</small></div></div>${state.tasks.filter(t=>t.status==='planned'&&t.date==='2026-09-10').map(t=>`<div class="time-row"><span class="time-label">${esc(t.time)}</span><div class="time-block ${t.area!=='Работа'?'personal':''}">${esc(t.title)}<small>${t.duration} мин · ${esc(t.area)}</small></div></div>`).join('')}<div class="time-row"><span class="time-label">14:00</span><div class="time-block free">Резерв на непредвиденное<small>Пример свободного блока</small></div></div></div></section>${!state.questionResolved?`<section class="panel"><div class="panel-head"><h2>Один вопрос</h2>${badge('ИИ','amber')}</div><div class="panel-body"><div class="question-box">Анна пишет: «Давай посмотрим договор на неделе». Создать задачу на проверку договора?</div><div class="actions">${button('Ответить','clarify','',true)}</div></div></section>`:''}<div class="note"><strong>План остаётся за вами</strong><br>Предложения попадут в календарь только после утверждения.</div></div></div><p class="footer-note">Последняя демонстрационная проверка: ${state.lastCheck}. Дата и примеры фиксированы; внешние сервисы не подключены.</p>`;}
function filteredMessages(){return state.messages.filter(m=>(inboxFilter==='all'||inboxFilter==='unread'&&!m.read||inboxFilter==='urgent'&&m.urgent||inboxFilter==='important'&&m.importance>=4||inboxFilter==='overdue'&&m.overdue)&&(sphere==='all'||m.area===sphere)&&(!search||`${m.title} ${m.summary} ${m.person}`.toLowerCase().includes(search.toLowerCase())));}
function inbox(){return heading('Входящие','Все сообщения в одном месте. Откройте материал, чтобы отметить интерес.')+`<div class="toolbar"><input class="search" id="search" aria-label="Поиск сообщений" placeholder="Поиск по сообщениям и отправителям" value="${esc(search)}"><select id="sphere" aria-label="Сфера интересов"><option value="all">Все сферы</option>${state.areas.map(a=>`<option ${sphere===a?'selected':''}>${esc(a)}</option>`).join('')}</select></div><div class="tabs">${Object.entries({all:'Все',unread:'Непрочитанные',urgent:'Срочные',important:'Важные',overdue:'Просроченные'}).map(([k,v])=>`<button class="tab ${inboxFilter===k?'active':''}" data-action="inbox-filter" data-id="${k}">${v}</button>`).join('')}</div><section class="panel" id="message-list">${filteredMessages().map(messageRow).join('')||'<div class="empty">По этим условиям сообщений нет. Измените поиск или фильтры.</div>'}</section>`;}
function tasks(){const shown=state.tasks.filter(t=>taskFilter==='all'||t.status===taskFilter);return heading('Задачи','Предложения ИИ, ваши решения и причины переносов.')+`<div class="tabs">${Object.entries({all:'Все',proposed:'На утверждение',planned:'Запланированы',overdue:'Нужно уточнить',done:'Выполнены'}).map(([k,v])=>`<button class="tab ${taskFilter===k?'active':''}" data-action="task-filter" data-id="${k}">${v}</button>`).join('')}</div><section class="panel">${shown.map(taskCard).join('')||'<div class="empty">В этой группе пока нет задач.</div>'}</section>`;}
function calendar(){return heading('Календарь','7–11 сентября 2026 · Europe/Madrid · демонстрационная рабочая неделя')+`<div class="note" style="margin-bottom:22px">Здесь отображаются только утверждённые задачи. Изменения в прототипе не отправляются в Google или Apple Calendar.</div><div class="week">${['Понедельник','Вторник','Среда','Четверг','Пятница'].map((day,i)=>`<section class="day ${i===3?'active-day':''}"><div class="day-title">${day}<b>${7+i}</b></div>${i===3?'<div class="calendar-event"><time>10:00–10:30</time>Встреча команды<br><small>Фиксировано</small></div>':''}${state.tasks.filter(t=>t.status==='planned'&&t.date===`2026-09-${String(7+i).padStart(2,'0')}`).map(t=>`<div class="calendar-event ${t.area!=='Работа'?'personal':''}"><time>${esc(t.time)} · ${t.duration} мин</time>${esc(t.title)}<div class="actions"><button class="link-button" data-action="edit-task" data-id="${t.id}">Изменить</button></div></div>`).join('')}${i<3?'<p class="form-hint">Нет запланированных задач</p>':''}${i===4?'<div class="calendar-event personal"><time>18:00–19:00</time>Визит мастера<br><small>Пример события</small></div>':''}</section>`).join('')}</div><div class="legend"><span>Работа / фиксированные встречи</span><span>Личные дела</span><span>Пустое пространство — свободное время</span></div><p class="footer-note">Пн–Чт 08:00–15:00 · Пт 08:00–14:00. В прототипе можно переносить задачи внутри показанной недели.</p>`;}
function questions(){return heading('Требует уточнения','Вы решаете, когда сообщение становится задачей.')+`<section class="panel">${state.questionResolved?'<div class="empty">Все вопросы решены. Новое предложение доступно в задачах, если вы выбрали его создание.</div>':messageRow(state.messages.find(m=>m.id===4))+`<div class="panel-body"><div class="question-box">Создать задачу на проверку договора или оставить сообщение для сведения? Срок в сообщении не указан точно.</div><div class="actions">${button('Ответить на вопрос','clarify','',true)}</div></div>`}</section>`;}
function sources(){return heading('Источники','Все представленные подключения — примеры будущего интерфейса.')+`<div class="source-grid">${[['Telegram','T','Каналы и личные сообщения'],['WhatsApp','W','Каналы и личные сообщения'],['E-mail','@','Все доступные входящие папки'],['RSS','R','Новые публикации лент'],['ВКонтакте','VK','Сообщения и публикации'],['YouTube','Y','Только названия и описания']].map(([name,icon,desc])=>`<article class="source-card"><div class="source-card-head"><span class="source-icon">${icon}</span><h3>${name}</h3></div>${badge('Демонстрация')}<p>${desc}</p><p>Проверка: каждые ${state.settings.interval} мин</p>${button('О подключении','source-info',name)}</article>`).join('')}</div><section class="panel section-space"><div class="panel-head"><h2>Пересмотреть подписки</h2>${badge(`${state.settings.inactivity} мес. без интереса`,'amber')}</div><div class="panel-body">${state.sourceHidden?'<p>«Новости каждый день» исключён из обработки в демонстрации. Подписка в Telegram не изменена.</p>'+button('Вернуть в обработку','restore-source'):state.sourceKept?'<p>Источник оставлен. Повторное предложение появится не раньше следующего полного периода.</p>':`<h3>Новости каждый день · Telegram</h3><p class="row-summary">В примере последнее открытие — 8 августа. Здесь показан будущий сценарий после накопления истории взаимодействий.</p><div class="note">Учитываются открытия в Message Hub. Чтение в Telegram в этом примере недоступно.</div><div class="actions">${button('Оставить','keep-source')}${button('Исключить из обработки','exclude-source')}${button('Как отписаться','unsubscribe')}</div>`}</div></section>`;}
function settings(){const s=state.settings;return heading('Настройки','Значения для первой версии. Изменения действуют только до перезагрузки страницы.')+`<form id="settings-form"><div class="settings-grid"><section class="panel"><div class="panel-head"><h2>Сбор и приоритеты</h2></div><div class="panel-body"><div class="form-row"><label for="interval">Проверять источники каждые</label><select id="interval" name="interval">${[15,30,60,120].map(v=>`<option value="${v}" ${v===s.interval?'selected':''}>${v===60?'1 час':v===120?'2 часа':v+' минут'}</option>`).join('')}</select></div><div class="form-row"><label for="urgent">Срочно, если до срока осталось часов</label><input id="urgent" name="urgent" type="number" min="1" max="168" value="${s.urgent}" required></div><div class="form-row"><label for="inactivity">Предложить пересмотр источника через месяцев</label><input id="inactivity" name="inactivity" type="number" min="1" max="12" value="${s.inactivity}" required></div><label class="checkbox-row"><input name="autostart" type="checkbox" ${s.autostart?'checked':''}>Запускать при входе рабочего пользователя</label><p class="form-hint">В прототипе настройка не изменяет автозапуск macOS.</p></div></section><section class="panel"><div class="panel-head"><h2>План и уведомления</h2></div><div class="panel-body"><div class="form-row"><label for="reserve">Резерв свободного времени, %</label><input id="reserve" name="reserve" type="number" min="0" max="50" value="${s.reserve}" required></div><div class="form-row"><label for="quietStart">Тихие часы — начало</label><input id="quietStart" name="quietStart" type="time" value="${s.quietStart}" required></div><div class="form-row"><label for="quietEnd">Тихие часы — конец</label><input id="quietEnd" name="quietEnd" type="time" value="${s.quietEnd}" required></div><div class="note">Работа: Пн–Чт 08:00–15:00, Пт 08:00–14:00.<br>Часовой пояс: Europe/Madrid.</div></div></section></div><div class="settings-actions"><button class="btn primary" type="submit">Сохранить настройки</button><span class="form-hint">Изменяются настройки демонстрации; реального сборщика пока нет.</span></div></form><section class="panel section-space"><div class="panel-head"><h2>Сферы интересов</h2></div><div class="panel-body"><div class="chips-editor">${state.areas.map((a,i)=>`<button class="chip-remove" data-action="remove-area" data-id="${i}" aria-label="Удалить сферу ${esc(a)}">${esc(a)}<span>×</span></button>`).join('')}</div><form id="area-form" class="form-inline"><input name="area" maxlength="50" placeholder="Новая сфера" aria-label="Название новой сферы" required><button class="btn" type="submit">Добавить</button></form></div></section><section class="panel"><div class="panel-head"><h2>Перенос и резервные копии</h2></div><div class="panel-body"><p class="row-summary">В полной системе: зашифрованная копия данных и настроек, восстановление под другим пользователем или на другом Mac.</p>${button('Скачать настройки прототипа','export')}<p class="form-hint">Скачивается JSON только с настройками демонстрации. Это не резервная копия будущей системы.</p></div></section>`;}
function render(){renderNav();$('#main').innerHTML=({today,inbox,tasks,calendar,questions,sources,settings}[view])();}
function navigate(){view=location.hash.slice(1);if(!routes[view])view='today';render();}
window.addEventListener('hashchange',navigate);
function openDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-header"><h2>${title}</h2><button class="close" data-action="close" aria-label="Закрыть">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();}
function messageDialog(id){const m=state.messages.find(x=>x.id===id);if(!m)return;m.read=true;render();openDialog(esc(m.title),`<div class="row-meta">${esc(m.person)} · ${m.source} · ${m.time}</div><div class="tags">${badge(m.area)}${badge(`Важность ${m.importance}/5`,'blue')}${m.deadline?badge(m.deadline,m.overdue?'red':''):''}</div><div class="original">${esc(m.body).replace(/\n/g,'<br>')}</div><p class="form-hint">Вымышленный текст. Открытие учтено как взаимодействие с источником в этой демонстрации.</p><form id="message-form" data-id="${m.id}"><div class="form-row"><label for="importance">Важность</label><select id="importance" name="importance">${[1,2,3,4,5].map(v=>`<option ${v===m.importance?'selected':''}>${v}</option>`).join('')}</select></div><div class="form-row"><label for="message-area">Сфера</label><select id="message-area" name="area">${[...new Set([...state.areas,m.area])].map(a=>`<option ${a===m.area?'selected':''}>${esc(a)}</option>`).join('')}</select></div><button class="btn primary" type="submit">Сохранить классификацию</button></form>`);}
function approveTask(id){const t=state.tasks.find(t=>t.id===id);if(!t||t.status!=='proposed')throw new Error('Задача не ожидает утверждения');t.status='planned';render();toast('Задача добавлена в демонстрационный календарь');return {id,status:t.status};}
function taskEditor(id,reason){const t=state.tasks.find(t=>t.id===id);if(!t)return;openDialog('Выбрать время',`<h3>${esc(t.title)}</h3>${reason?`<p class="row-summary">Причина: ${esc(reason)}</p>`:''}<form id="task-form" data-id="${id}" data-reason="${esc(reason||'')}"><div class="form-row"><label for="task-date">Дата</label><input id="task-date" name="date" type="date" min="2026-09-10" max="2026-09-11" value="${t.date<'2026-09-10'?'2026-09-10':t.date}" required><p class="form-hint">Для примера доступны 10 и 11 сентября. В полной версии — выбор любой подходящей даты.</p></div><div class="form-row"><label for="task-time">Начало</label><input id="task-time" name="time" type="time" value="${t.status==='overdue'?'13:30':t.time}" required></div><div class="form-row"><label for="duration">Длительность, минут</label><input id="duration" name="duration" type="number" min="5" max="480" step="5" value="${reason==='Задача сложнее ожидаемого'?t.duration*2:t.duration}" required></div><div class="note">Нажатие кнопки подтверждает время в демонстрационном календаре. Полный планировщик конфликтов в прототипе не реализован.</div><div class="actions"><button class="btn primary" type="submit">Подтвердить время</button>${button('Отмена','close')}</div></form>`);}
function reasonDialog(id){openDialog('Почему задача не сделана?',`<p class="row-summary">Причина поможет предложить более подходящий план.</p><form id="reason-form" data-id="${id}"><div class="form-row"><label for="reason">Причина</label><select id="reason" name="reason">${['Не хватило времени','Жду других','Изменились приоритеты','Задача сложнее ожидаемого','Другая причина'].map(r=>`<option>${r}</option>`).join('')}</select></div><div class="form-row" id="other-reason-row" hidden><label for="other">Ваш вариант</label><textarea id="other" name="other" rows="3" maxlength="500"></textarea></div><div class="actions"><button class="btn primary" type="submit">Предложить перенос</button>${button('Отвечу позже','close')}</div></form>`);}
function clarify(){openDialog('Нужна ли задача по договору?',`<div class="original">«Давай посмотрим договор на неделе»</div><p>ИИ предлагает: «Проверить условия договора», 30 минут. Точный срок не указан — время будет предложением.</p><div class="actions">${button('Да, предложить задачу','resolve-yes','',true)}${button('Нет, только информация','resolve-no')}</div>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const id=Number(b.dataset.id),action=b.dataset.action,t=state.tasks.find(t=>t.id===id);switch(action){
case 'close':closeDialog();break;
case 'message':messageDialog(id);break;
case 'check':state.lastCheck='10:01';render();toast('Демо-проверка завершена. Реальные источники не подключены.');break;
case 'inbox-filter':inboxFilter=b.dataset.id;render();break;
case 'task-filter':taskFilter=b.dataset.id;render();break;
case 'approve':approveTask(id);break;
case 'edit-task':taskEditor(id);break;
case 'done':if(t){t.status='done';render();toast('Задача отмечена выполненной');}break;
case 'defer':if(t){t.status='deferred';render();toast('Задача отложена, её можно найти во всех задачах');}break;
case 'reject':if(t){t.status='rejected';render();toast('Предложение отклонено');}break;
case 'reason':reasonDialog(id);break;
case 'task-sources':if(t)openDialog('Исходные сообщения',t.messages.map(mid=>messageRow(state.messages.find(m=>m.id===mid))).join(''));break;
case 'clarify':clarify();break;
case 'resolve-yes':if(!state.questionResolved){state.tasks.push({id:5,title:'Проверить условия договора',area:'Работа',importance:3,deadline:'Не указан',slot:'Пятница, 10:00–10:30',date:'2026-09-11',time:'10:00',duration:30,status:'proposed',messages:[4],explanation:'Срок не указан. Пятница предложена ИИ и требует вашего утверждения.'});state.questionResolved=true;}closeDialog();render();toast('Создано предложение задачи. Время ещё не утверждено.');break;
case 'resolve-no':state.questionResolved=true;closeDialog();render();toast('Оставлено как информация');break;
case 'source-info':openDialog(esc(b.dataset.id),'<p>Это пример карточки источника. При разработке будут проверены доступные способы подключения, охват сообщений и ограничения сервиса.</p><p class="note">Ни один аккаунт в прототипе не подключён. Данные доступа здесь вводить не нужно.</p>');break;
case 'keep-source':state.sourceKept=true;render();toast('Источник оставлен');break;
case 'exclude-source':openDialog('Исключить источник из обработки?',`<p>«Новости каждый день» перестанет попадать в обработку демонстрации. Подписка в Telegram останется.</p><div class="actions">${button('Исключить','confirm-exclude','',true)}${button('Отмена','close')}</div>`);break;
case 'confirm-exclude':state.sourceHidden=true;closeDialog();render();toast('Источник исключён только в демонстрации');break;
case 'restore-source':state.sourceHidden=false;state.sourceKept=false;render();break;
case 'unsubscribe':openDialog('Отписка в исходном сервисе','<p>В полной системе здесь будет переход к каналу для отписки. В этом примере канал вымышленный, внешнее действие не выполняется.</p>');break;
case 'remove-area':{const area=state.areas[id];state.areas.splice(id,1);state.messages.forEach(m=>{if(m.area===area)m.area='Без категории';});state.tasks.forEach(t=>{if(t.area===area)t.area='Без категории';});render();toast('Сфера удалена. Её материалы сохранены без категории.');break;}
case 'export':{const blob=new Blob([JSON.stringify({prototype:true,date:'2026-09-10',settings:state.settings,areas:state.areas},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='message-hub-demo-settings.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Скачаны настройки демонстрации');break;}
}});
document.addEventListener('input',e=>{if(e.target.id==='search'){search=e.target.value;$('#message-list').innerHTML=filteredMessages().map(messageRow).join('')||'<div class="empty">Ничего не найдено.</div>';}});
document.addEventListener('change',e=>{if(e.target.id==='sphere'){sphere=e.target.value;render();}if(e.target.id==='reason'){const other=e.target.value==='Другая причина';$('#other-reason-row').hidden=!other;$('#other').required=other;}});
document.addEventListener('submit',e=>{const form=e.target;if(!['settings-form','message-form','task-form','reason-form','area-form'].includes(form.id))return;e.preventDefault();const data=new FormData(form);const t=state.tasks.find(t=>t.id===Number(form.dataset.id));switch(form.id){
case 'settings-form':state.settings={interval:Number(data.get('interval')),inactivity:Number(data.get('inactivity')),urgent:Number(data.get('urgent')),reserve:Number(data.get('reserve')),quietStart:data.get('quietStart'),quietEnd:data.get('quietEnd'),autostart:data.has('autostart')};render();toast('Настройки демонстрации сохранены');break;
case 'area-form':{const area=data.get('area').trim();if(area&&!state.areas.includes(area)){state.areas.push(area);render();toast('Сфера добавлена');}else toast('Введите новое название сферы');break;}
case 'message-form':{const m=state.messages.find(m=>m.id===Number(form.dataset.id));m.importance=Number(data.get('importance'));m.area=data.get('area');closeDialog();render();toast('Классификация изменена');break;}
case 'task-form':t.date=data.get('date');t.time=data.get('time');t.duration=Number(data.get('duration'));t.slot=`${t.date==='2026-09-10'?'Сегодня':'Пятница'}, ${t.time} · ${t.duration} мин`;t.status='planned';if(form.dataset.reason)t.reason=form.dataset.reason;t.explanation='Время подтверждено пользователем.';closeDialog();render();toast('Новое время подтверждено в демонстрации');break;
case 'reason-form':{const reason=data.get('reason')==='Другая причина'?data.get('other').trim():data.get('reason');if(!reason){toast('Укажите причину');return;}taskEditor(t.id,reason);break;}
}});
$('#reset').addEventListener('click',()=>{resetState();inboxFilter='all';taskFilter='all';sphere='all';search='';closeDialog();render();toast('Демонстрационные данные восстановлены');});
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=$('#dialog').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
navigate();
// Optional browser-agent access uses the same state and actions as the visible prototype.
if(document.modelContext?.registerTool){const lifetime=new AbortController();const tools=[{name:'message_hub_read_demo_tasks',description:'Read tasks in the local demonstration. No real accounts are connected.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>state.tasks.map(({id,title,status})=>({id,title,status}))},{name:'message_hub_approve_demo_task',description:'Approve a proposed demo task and add it to the visible demo calendar. Does not modify an external calendar.',inputSchema:{type:'object',properties:{id:{type:'integer'}},required:['id'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||!Number.isInteger(input.id))throw new Error('Expected integer task id');return approveTask(input.id);}}];for(const tool of tools){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifetime.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifetime.abort(),{once:true});}
